<?php
 namespace QQWorld\Shipping\Model; use QQWorld\Framework\DataObject; use QQWorld\Framework\ObjectManagerInterface; use QQWorld\Quote\Model\Quote\Address\RateResult\Method; use QQWorld\Shipping\Model\Rate\Result; use QQWorld\TestFramework\Helper\Bootstrap; class ShippingTest extends \PHPUnit\Framework\TestCase { private $model; private $objectManager; protected function setUp() { $this->objectManager = Bootstrap::getObjectManager(); $this->model = $this->objectManager->get(Shipping::class); } public function testCollectRatesByAddress() { $address = $this->objectManager->create(DataObject::class, [ 'data' => [ 'region_id' => 'CA', 'postcode' => '11111', 'lastname' => 'John', 'firstname' => 'Doe', 'street' => 'Some street', 'city' => 'Los Angeles', 'email' => 'john.doe@example.com', 'telephone' => '11111111', 'country_id' => 'US', 'item_qty' => 1 ] ]); $result = $this->model->collectRatesByAddress($address, 'flatrate'); static::assertInstanceOf(Shipping::class, $result); return $result->getResult(); } public function testCollectRates(Result $result) { $rates = $result->getAllRates(); static::assertNotEmpty($rates); $rate = array_pop($rates); static::assertInstanceOf(Method::class, $rate); static::assertEquals('flatrate', $rate->getData('carrier')); static::assertEquals(5, $rate->getData('price')); } } 